impl<'a, 'b> SettleCnftSaleCpi<'a, 'b> {
    pub fn new(
        program: &'b solana_account_info::AccountInfo<'a>,
        accounts: SettleCnftSaleCpiAccounts<'a, 'b>,
        args: SettleCnftSaleInstructionArgs,
    ) -> Self {
        Self {
            __program: program,
            payer: accounts.payer,
            gumball_machine: accounts.gumball_machine,
            authority_pda: accounts.authority_pda,
            authority_pda_payment_account: accounts.authority_pda_payment_account,
            authority: accounts.authority,
            authority_payment_account: accounts.authority_payment_account,
            seller: accounts.seller,
            seller_payment_account: accounts.seller_payment_account,
            seller_history: accounts.seller_history,
            buyer: accounts.buyer,
            fee_account: accounts.fee_account,
            fee_payment_account: accounts.fee_payment_account,
            payment_mint: accounts.payment_mint,
            token_program: accounts.token_program,
            associated_token_program: accounts.associated_token_program,
            system_program: accounts.system_program,
            rent: accounts.rent,
            tree_config: accounts.tree_config,
            merkle_tree: accounts.merkle_tree,
            log_wrapper: accounts.log_wrapper,
            compression_program: accounts.compression_program,
            bubblegum_program: accounts.bubblegum_program,
            event_authority: accounts.event_authority,
            program: accounts.program,
            __args: args,
        }
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], &[])
    }
    #[inline(always)]
    pub fn invoke_with_remaining_accounts(
        &self,
        remaining_accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], remaining_accounts)
    }
    #[inline(always)]
    pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(signers_seeds, &[])
    }
    #[allow(clippy::arithmetic_side_effects)]
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed_with_remaining_accounts(
        &self,
        signers_seeds: &[&[&[u8]]],
        remaining_accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> solana_program_error::ProgramResult {
        let mut accounts = Vec::with_capacity(24 + remaining_accounts.len());
        accounts.push(solana_instruction::AccountMeta::new(*self.payer.key, true));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.gumball_machine.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.authority_pda.key,
            false,
        ));
        if let Some(authority_pda_payment_account) = self.authority_pda_payment_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *authority_pda_payment_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new(
            *self.authority.key,
            false,
        ));
        if let Some(authority_payment_account) = self.authority_payment_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *authority_payment_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new(
            *self.seller.key,
            false,
        ));
        if let Some(seller_payment_account) = self.seller_payment_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *seller_payment_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new(
            *self.seller_history.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.buyer.key,
            false,
        ));
        if let Some(fee_account) = self.fee_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *fee_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        if let Some(fee_payment_account) = self.fee_payment_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *fee_payment_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        if let Some(payment_mint) = self.payment_mint {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                *payment_mint.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::MALLOW_GUMBALL_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.token_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.associated_token_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.system_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.rent.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.tree_config.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.merkle_tree.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.log_wrapper.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.compression_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.bubblegum_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.event_authority.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.program.key,
            false,
        ));
        remaining_accounts.iter().for_each(|remaining_account| {
            accounts.push(solana_instruction::AccountMeta {
                pubkey: *remaining_account.0.key,
                is_signer: remaining_account.1,
                is_writable: remaining_account.2,
            })
        });
        let mut data = SettleCnftSaleInstructionData::new().try_to_vec().unwrap();
        let mut args = self.__args.try_to_vec().unwrap();
        data.append(&mut args);

        let instruction = solana_instruction::Instruction {
            program_id: crate::MALLOW_GUMBALL_ID,
            accounts,
            data,
        };
        let mut account_infos = Vec::with_capacity(25 + remaining_accounts.len());
        account_infos.push(self.__program.clone());
        account_infos.push(self.payer.clone());
        account_infos.push(self.gumball_machine.clone());
        account_infos.push(self.authority_pda.clone());
        if let Some(authority_pda_payment_account) = self.authority_pda_payment_account {
            account_infos.push(authority_pda_payment_account.clone());
        }
        account_infos.push(self.authority.clone());
        if let Some(authority_payment_account) = self.authority_payment_account {
            account_infos.push(authority_payment_account.clone());
        }
        account_infos.push(self.seller.clone());
        if let Some(seller_payment_account) = self.seller_payment_account {
            account_infos.push(seller_payment_account.clone());
        }
        account_infos.push(self.seller_history.clone());
        account_infos.push(self.buyer.clone());
        if let Some(fee_account) = self.fee_account {
            account_infos.push(fee_account.clone());
        }
        if let Some(fee_payment_account) = self.fee_payment_account {
            account_infos.push(fee_payment_account.clone());
        }
        if let Some(payment_mint) = self.payment_mint {
            account_infos.push(payment_mint.clone());
        }
        account_infos.push(self.token_program.clone());
        account_infos.push(self.associated_token_program.clone());
        account_infos.push(self.system_program.clone());
        account_infos.push(self.rent.clone());
        account_infos.push(self.tree_config.clone());
        account_infos.push(self.merkle_tree.clone());
        account_infos.push(self.log_wrapper.clone());
        account_infos.push(self.compression_program.clone());
        account_infos.push(self.bubblegum_program.clone());
        account_infos.push(self.event_authority.clone());
        account_infos.push(self.program.clone());
        remaining_accounts
            .iter()
            .for_each(|remaining_account| account_infos.push(remaining_account.0.clone()));

        if signers_seeds.is_empty() {
            solana_cpi::invoke(&instruction, &account_infos)
        } else {
            solana_cpi::invoke_signed(&instruction, &account_infos, signers_seeds)
        }
    }
}

/// Instruction builder for `SettleCnftSale` via CPI.
///
/// ### Accounts:
///
///   0. `[writable, signer]` payer
///   1. `[writable]` gumball_machine
///   2. `[writable]` authority_pda
///   3. `[writable, optional]` authority_pda_payment_account
///   4. `[writable]` authority
///   5. `[writable, optional]` authority_payment_account
///   6. `[writable]` seller
///   7. `[writable, optional]` seller_payment_account
///   8. `[writable]` seller_history
///   9. `[]` buyer
///   10. `[writable, optional]` fee_account
///   11. `[writable, optional]` fee_payment_account
///   12. `[optional]` payment_mint
///   13. `[]` token_program
///   14. `[]` associated_token_program
///   15. `[]` system_program
///   16. `[]` rent
///   17. `[]` tree_config
///   18. `[writable]` merkle_tree
///   19. `[]` log_wrapper
///   20. `[]` compression_program
///   21. `[]` bubblegum_program
///   22. `[]` event_authority
///   23. `[]` program
#[derive(Clone, Debug)]
pub struct SettleCnftSaleCpiBuilder<'a, 'b> {
    instruction: Box<SettleCnftSaleCpiBuilderInstruction<'a, 'b>>,
}

